+using System.Diagnostics;
+using System.Runtime.CompilerServices;
+using CombatSolver.Engine.Common;
+using CombatSolver.Engine.InCombat.Simulation;
+
+namespace CombatSolver;
+
+internal sealed partial class CombatBeamSolver
+{
+    // Research only. Keep the original complete Snapshot and every candidate.
+    private sealed class DefeatSnapshotOpportunityTotals
+    {
+        internal long Snapshots, DeadSnapshots, DefeatStamps, SourceEligible,
+            PolicyEligible, Witnesses, Completed, Ticks;
+    }
+
+    private static readonly ConditionalWeakTable<SearchRequestWorkTotals,
+        DefeatSnapshotOpportunityTotals> DefeatSnapshotOpportunities = new();
+
+    private long BeginDefeatSnapshotOpportunity(CombatPredictionSimulator simulator,
+        bool dead, bool risk, SearchBoundaryReason boundary)
+    {
+        var totals = DefeatSnapshotOpportunities.GetValue(_replayWork, static _ => new());
+        Interlocked.Increment(ref totals.Snapshots);
+        if (!dead) return 0;
+        Interlocked.Increment(ref totals.DeadSnapshots);
+        if (simulator.TerminalStamp is not { Outcome: CombatTerminalOutcome.Defeat }
+            || simulator.HasPendingChoice || risk || boundary != SearchBoundaryReason.None)
+            return 0;
+        Interlocked.Increment(ref totals.DefeatStamps);
+        if (!root.UsesPruningComponentHealingCertificate) return 0;
+        Interlocked.Increment(ref totals.SourceEligible);
+        if (_potionStrategy.HasForcedDirectives
+            || _theftPolicy == SolverTheftPolicy.PreserveResources
+            || policy.RelicTargets.Count != 0)
+            return 0;
+        int tier;
+        if (_minimumPotionUses == 0
+            && _potionPolicy is SolverPotionPolicy.Disabled or SolverPotionPolicy.Smart)
+            tier = 0;
+        else if (_minimumPotionUses > 0 && _maximumPotionUses == _minimumPotionUses
+            && _potionFreePolicyBaseline is { Won: true, DeathSaveUseCount: 0 })
+            tier = _minimumPotionUses;
+        else return 0;
+        Interlocked.Increment(ref totals.PolicyEligible);
+        if (!_useSharedPrimaryIncumbents
+            || !_primaryIncumbents.TryGetStrictHpWitness(0, tier, int.MaxValue, out _))
+            return 0;
+        Interlocked.Increment(ref totals.Witnesses);
+        return Stopwatch.GetTimestamp();
+    }
+
+    private void EndDefeatSnapshotOpportunity(long started)
+    {
+        if (started == 0) return;
+        var totals = DefeatSnapshotOpportunities.GetValue(_replayWork, static _ => new());
+        Interlocked.Increment(ref totals.Completed);
+        Interlocked.Add(ref totals.Ticks, Stopwatch.GetTimestamp() - started);
+    }
+
+    private void EmitDefeatSnapshotOpportunity()
+    {
+        var totals = DefeatSnapshotOpportunities.GetValue(_replayWork, static _ => new());
+        policy.Diagnostics.Info($"[CombatSolver/Test] DEFEAT_SNAPSHOT_OPPORTUNITY "
+            + $"cumulative=true snapshots={totals.Snapshots} dead={totals.DeadSnapshots} "
+            + $"defeat={totals.DefeatStamps} source={totals.SourceEligible} policy={totals.PolicyEligible} "
+            + $"witness={totals.Witnesses} completed={totals.Completed} "
+            + $"snapshot_tail_ms={totals.Ticks * 1000d / Stopwatch.Frequency:F3}");
+    }
+}

